import {chinaDate} from './cloud-contract.mjs';
const decimal=n=>Math.floor(n/100)+'.'+String(n%100).padStart(2,'0');
export function createCostSourcesEditors({api,h,mount,input,area,select}){
 async function referenceCost(id,month=chinaDate().slice(0,7)){
  const state=await api.referenceCost(id,month),key=crypto.randomUUID(),r=state.current;
  mount('参考成本与履约方式',`<p>${h(state.sku.code)} · ${h(state.sku.name)}</p>`+input('effectiveMonth','生效月份',month,'type="month" required min="1900-01" max="2199-12"')+
   input('unitPrice','参考单价（元，留空停止使用估算）',r?.unitCents==null?'':decimal(r.unitCents),'inputmode="decimal" maxlength="11"')+
   select('fulfillmentMode','该期默认履约方式',r?.fulfillmentMode||'stocked',[['stocked','工作室备货'],['dropship','一件代发']])+input('sourceReference','参考依据',r?.sourceReference,'required maxlength="200"')+
   area('reason','本次登记或调整说明')+'<p class="muted">参考单价仅用于明确标记的估算。实际库存成本保持独立；已保存代发批次保留当时依据。默认方式用于该期参考，不迁移或隐藏已有业务。</p>',f=>api.saveReferenceCost(id,{requestKey:key,expectedVersion:state.version,effectiveMonth:f.get('effectiveMonth'),unitPrice:f.get('unitPrice').trim()||null,fulfillmentMode:f.get('fulfillmentMode'),sourceReference:f.get('sourceReference'),reason:f.get('reason')}),{kind:'reference-cost',id,month},()=>api.referenceCostReceipt(id,key));
 }
 async function dropship(id=null,replacesId=null){
  const key=crypto.randomUUID(),state=id?await api.dropshipDetail(id):null,options=id?null:await api.dropshipOptions();
  if(state?.record.status==='void')throw new Error('原批次已作废，请从重建入口登记正确记录。');
  const origin=replacesId?await api.dropshipDetail(replacesId):null;if(origin&&(origin.record.status!=='void'||origin.document.replacementId))throw new Error('请从尚未重建的已作废批次进入。');
  let indices=origin?origin.lines.map((_,i)=>i):[0],next=indices.length;
  const price=(i,r)=>select('basis'+i,'成本依据',r?.basis||'actual',[['actual','已核实的实际总成本'],['reference','按业务月份参考单价估算']])+input('amount'+i,'实际总成本（元，参考估算留空）',r?.basis==='actual'?decimal(r.amountCents):'','inputmode="decimal" maxlength="11"');
  const row=i=>{const old=origin?.lines[i],oldPrice=old&&origin.record.lines.find(c=>c.lineId===old.id);return `<fieldset data-drop-row="${i}"><legend>代发明细</legend>${input('sku'+i,'SKU 编号',old?.snapshot.skuCode||'','required list="drop-sku-list" maxlength="64"')}${select('store'+i,'业务店铺',old?.storeId||'',[['','请选择'],...options.stores.map(s=>[s.id,s.name])])}${input('quantity'+i,'实际代发数量',old?.quantity||'1','required type="number" min="1" max="2147483647" step="1"')}${price(i,oldPrice)}<button type="button" class="text-button" data-drop-remove="${i}">移除此行</button></fieldset>`;};
  const doc=state?.document,body=state?`<p>${h(doc.code)} · ${h(doc.businessDate)} · ${h(doc.supplier)}</p>`+state.lines.map((line,i)=>`<fieldset><legend>${h(line.snapshot.skuCode)} · ${h(line.snapshot.name)} · ${h(line.snapshot.storeName)} · ${line.quantity} ${h(line.snapshot.unit)}</legend>${price(i,state.record.lines.find(c=>c.lineId===line.id))}</fieldset>`).join(''):
   (origin?`<p class="planning-rule">关联原错单 ${h(origin.document.code)} 重建；请重新核对日期、数量、店铺和总成本，原作废单保留。</p>`:'')+input('code','代发批次编号',origin?origin.document.code.slice(0,60)+'-R1':'','required maxlength="64"')+input('businessDate','实际代发日期',origin?.document.businessDate||chinaDate(),'required type="date"')+input('supplier','代发供应商',origin?.document.supplier||'','required maxlength="150"')+input('sourceReference','原代发清单或结算单编号',origin?.document.sourceReference||'','required maxlength="200"')+`<datalist id="drop-sku-list">${options.rows.map(s=>`<option value="${h(s.code)}">${h(s.name)} ${h(s.specification)}</option>`).join('')}</datalist><p class="muted">可直接填写正式 SKU 编号，建议列表展示前 50 个启用商品。每批最多 100 行，可包含多个 SKU 和店铺。</p><div data-drop-lines>${indices.map(row).join('')}</div><button type="button" class="secondary" data-drop-add>＋ 添加明细</button>`;
  mount(state?'修正代发成本':'登记代发成本批次',body+area('reason','成本核对依据与说明')+'<p class="muted">实际总成本包含本行已核实的附加费。选择参考估算时，使用保存时该业务月份适用的单价，并保留快照。保存成本不扣工作室库存，不自动生成支出或付款。</p>',f=>api.saveDropship(id,state?{requestKey:key,expectedVersion:state.record.version,reason:f.get('reason'),lines:state.lines.map((line,i)=>({lineId:line.id,basis:f.get('basis'+i),amount:f.get('basis'+i)==='reference'?null:f.get('amount'+i).trim()}))}:{requestKey:key,...(replacesId?{replacesId}:{}),code:f.get('code'),businessDate:f.get('businessDate'),supplier:f.get('supplier'),sourceReference:f.get('sourceReference'),reason:f.get('reason'),lines:indices.map(i=>({skuCode:f.get('sku'+i),storeId:f.get('store'+i),quantity:Number(f.get('quantity'+i)),basis:f.get('basis'+i),amount:f.get('basis'+i)==='reference'?null:f.get('amount'+i).trim()}))}),{kind:'dropship-cost',id},()=>api.dropshipReceipt(key,id?'revise':'create',id),state?undefined:form=>{
   const click=e=>{if(form.querySelector('[type=submit]').disabled)return;const remove=e.target.closest('[data-drop-remove]');if(e.target.closest('[data-drop-add]')&&indices.length<100){const i=next++;indices.push(i);form.querySelector('[data-drop-lines]').insertAdjacentHTML('beforeend',row(i));form.dispatchEvent(new Event('input'));}if(remove&&indices.length>1){const i=Number(remove.dataset.dropRemove);indices=indices.filter(n=>n!==i);remove.closest('[data-drop-row]').remove();form.dispatchEvent(new Event('input'));}};
   form.addEventListener('click',click);return ()=>form.removeEventListener('click',click);
  });
 }
 async function dropshipRefund(id,refundId=null,replacesRefundId=null){
  const state=await api.dropshipDetail(id),old=refundId?state.refunds.find(r=>r.id===refundId):null,key=crypto.randomUUID(),latest=old?.history[0];
  if(state.record.status!=='active')throw new Error('原代发批次已作废。');
  const origin=replacesRefundId?state.refunds.find(r=>r.id===replacesRefundId):null;if(replacesRefundId&&(!origin||origin.history[0].status!=='void'||origin.replacementId))throw new Error('请从尚未重建的已作废退款进入。');if(old?.history[0].status==='void')throw new Error('原退款已作废。');
  if(refundId&&!old)throw new Error('原退款暂不可见。');
  const available=state.lines.filter(l=>l.quantity>l.returnedQuantity);if(!old&&!available.length)throw new Error('原批次已无可退数量。');
  const body=old?`<p>修正原退款 · ${h(old.businessDate)} · 数量 ${old.quantity} · ${h(old.sourceReference)}</p>`:
   (origin?`<p>关联原作废退款 ${h(origin.sourceReference)} 重建，请核对正确日期、数量和原明细。</p>`:'')+select('lineId','原代发明细',available.some(l=>l.id===origin?.lineId)?origin.lineId:available[0].id,available.map(l=>[l.id,`${l.snapshot.skuCode} · ${l.snapshot.storeName} · 尚可退 ${l.quantity-l.returnedQuantity} ${l.snapshot.unit}`]))+input('quantity','本次退货数量',origin?.quantity||'1','required type="number" min="1" max="2147483647" step="1"')+input('businessDate','供应商实际退款日期',origin?.businessDate||chinaDate(),'required type="date"')+input('sourceReference','供应商退款单号或来源编号',origin?.sourceReference||'','required maxlength="200"');
  mount(old?'修正供应商退款金额':'登记代发退货退款',body+input('amount','供应商实际退回金额（元）',latest?decimal(latest.amountCents):origin?decimal(origin.history[0].amountCents):'','required inputmode="decimal" maxlength="11"')+area('reason','退款核对或修正说明')+'<p class="muted">按供应商实际退款核实录入，不按原单价自动推算。回冲记入退款日期所在月份，不增加工作室库存。</p>',f=>api.saveDropshipRefund(id,{requestKey:key,refundId,...(replacesRefundId?{replacesRefundId}:{}),expectedVersion:latest?.version??0,lineId:old?.lineId||f.get('lineId'),quantity:old?.quantity||Number(f.get('quantity')),businessDate:old?.businessDate||f.get('businessDate'),sourceReference:old?.sourceReference||f.get('sourceReference'),amount:f.get('amount').trim(),reason:f.get('reason')}),{kind:'dropship-cost',id},()=>api.dropshipReceipt(key,'refund',id));
 }
 async function dropshipFacts(id){
  const [s,options]=await Promise.all([api.dropshipDetail(id),api.dropshipOptions()]),key=crypto.randomUUID();if(s.record.status!=='active')throw new Error('原批次已作废。');
  const activeRefunds=s.refunds.filter(r=>r.history[0].status==='active'),latestRefundDay=activeRefunds.map(r=>r.businessDate).sort()[0],stores=[...options.stores];for(const l of s.lines)if(!stores.some(v=>v.id===l.storeId))stores.push({id:l.storeId,name:l.snapshot.storeName+'（原店铺）'});
  const body=`<p>${h(s.document.code)} · 保留原批次、明细及真实退款标识，追加更正版本。</p>`+input('businessDate','正确的实际代发日期',s.document.businessDate,'required type="date"'+(latestRefundDay?` max="${h(latestRefundDay)}"`:''))+input('supplier','正确供应商',s.document.supplier,'required maxlength="150"')+input('sourceReference','正确原清单／结算单编号',s.document.sourceReference,'required maxlength="200"')+
   s.lines.map((l,i)=>{const c=s.record.lines.find(c=>c.lineId===l.id);return `<fieldset><legend>原明细 ${i+1} · ${h(l.snapshot.skuCode)} · 已有效退货 ${l.returnedQuantity} ${h(l.snapshot.unit)}</legend>`+input('sku'+i,'正确 SKU 编号',l.snapshot.skuCode,'required maxlength="64"'+(l.returnedQuantity?' readonly':''))+select('store'+i,'正确业务店铺',l.storeId,stores.map(v=>[v.id,v.name]))+input('quantity'+i,'正确代发数量',l.quantity,`required type="number" min="${Math.max(1,l.returnedQuantity)}" max="2147483647" step="1"`)+select('basis'+i,'成本依据',c.basis,[['actual','已核实实际总成本'],['reference','按正确月份参考价估算']])+input('amount'+i,'正确实际总成本（元，参考估算留空）',c.basis==='actual'?decimal(c.amountCents):'','inputmode="decimal" maxlength="11"')+'</fieldset>';}).join('')+
   '<p class="muted">有真实退款时保留原退款金额、日期和数量，不得把代发日期改到退款之后，也不得把数量改到已退数量以下。本行有真实退款时不能直接换SKU。数量改变不会按比例猜测总成本，请重新核对。</p>'+area('reason','原错误内容和更正依据（必填）');
  mount('更正代发日期、数量与店铺',body,f=>api.correctDropshipFacts(id,{requestKey:key,expectedVersion:s.record.version,businessDate:f.get('businessDate'),supplier:f.get('supplier'),sourceReference:f.get('sourceReference'),reason:f.get('reason'),lines:s.lines.map((l,i)=>({lineId:l.id,skuCode:f.get('sku'+i),storeId:f.get('store'+i),quantity:Number(f.get('quantity'+i)),basis:f.get('basis'+i),amount:f.get('basis'+i)==='reference'?null:f.get('amount'+i).trim()}))}),{kind:'dropship-cost',id},()=>api.dropshipReceipt(key,'facts',id));
 }
 async function dropshipVoid(id,refundId=null){
  const s=await api.dropshipDetail(id),r=refundId?s.refunds.find(r=>r.id===refundId)?.history[0]:s.record,key=crypto.randomUUID();
  if(!r||r.status!=='active'||s.record.status!=='active')throw new Error('原记录已变化或已作废。');
  if(!refundId&&s.refunds.some(r=>r.history[0].status==='active'))throw new Error('原批次仍有有效退款，请先核实实际业务和错误退款，不能连带作废。');
  mount(refundId?'作废错误退款登记':'作废错误代发批次',`<p>${h(s.document.code)}${refundId?' · '+h(s.refunds.find(r=>r.id===refundId).sourceReference):''}</p><p>只作废错误登记，保留全部历史，并移出有效成本／退款汇总。这不代表实际退货、撤回付款或撤销供应商退款，也不会改工作室库存、支出或现金记录。真实发生的业务请保留原记录。</p>`+area('reason','错误内容和作废依据（必填）'),f=>api.voidDropship(id,{requestKey:key,expectedVersion:r.version,reason:f.get('reason')},refundId),{kind:'dropship-cost',id},()=>api.dropshipReceipt(key,refundId?'refund-void':'void',id,refundId));
 }
 return {referenceCost,dropship,dropshipRefund,dropshipVoid,dropshipFacts};
}
